xpath.attribute:
button next validation btn btn-primary btn-lg w-50 py-3 lh-lg
{{
    (
        currentOrder.isPaid()
        or (
            currentOrder.is_partial_payment
            and currentOrder.get_total_paid() > 0
        )
    )
    and currentOrder._isValidEmptyOrder()
    and !currentOrder.isRefundInProcess()
    ? 'highlight'
    : 'disabled'
}}
